## 3️⃣ HashAggregationOperator – In‑Memory Group‑By

```csharp
using System.Collections.Immutable;

// ---------------------------------------------------------------
// 3.1  Aggregation state – you can extend this with more functions.
// ---------------------------------------------------------------
public sealed class AggregationState
{
    public long Count { get; private set; }
    public double Sum { get; private set; }

    public void Add(Row row, int valueColumnIndex)
    {
        Count++;
        if (row.Values[valueColumnIndex] is IConvertible c)
            Sum += c.ToDouble(null);
    }

    public static AggregationState Merge(AggregationState a, AggregationState b) =>
        new() { Count = a.Count + b.Count, Sum = a.Sum + b.Sum };
}

// ---------------------------------------------------------------
// 3.2  Aggregation configuration
// ---------------------------------------------------------------
public sealed class HashAggConfig
{
    public int[] GroupByColumnIndices { get; init; } = default!; // e.g. {0,2}
    public int AggregateValueColumnIndex { get; init; } = 1;      // column to SUM
    public ISpillManager SpillManager { get; init; } = default!;
    public long MemoryBudgetBytes { get; init; } = 64 * 1024 * 1024; // 64 MiB
}

// ---------------------------------------------------------------
// 3.3  HashAggregationOperator
// ---------------------------------------------------------------
public sealed class HashAggregationOperator : IOperator
{
    private readonly IOperator _upstream;
    private readonly HashAggConfig _cfg;
    private readonly CancellationTokenSource _cts = new();

    // The hash table: key → state
    private readonly ConcurrentDictionary<object?, AggregationState> _hashTable = new();
    private readonly object _sizeLock = new();
    private long _approxSizeBytes; // rough estimate for eviction decisions

    public HashAggregationOperator(IOperator upstream, HashAggConfig cfg)
    {
        _upstream = upstream;
        _cfg = cfg;
    }

    public async ValueTask<IReadOnlyList<Row>> GetNextBatchAsync(CancellationToken ct = default)
    {
        // Pull a batch from upstream, aggregate it, then return **nothing**.
        // The final result is produced when the upstream signals EOS (empty batch).
        var batch = await _upstream.GetNextBatchAsync(ct).ConfigureAwait(false);
        if (batch.Count == 0) // upstream finished → emit final groups
            return EmitFinalResult();

        foreach (var row in batch)
            ProcessRow(row);

        // The aggregation operator does not produce rows per‑batch.
        return Array.Empty<Row>();
    }

    private void ProcessRow(Row row)
    {
        // Build a composite key from the group‑by columns.
        var key = CreateKey(row);

        // Fast path – try to get or add the state.
        var state = _hashTable.GetOrAdd(key, _ => new AggregationState());
        state.Add(row, _cfg.AggregateValueColumnIndex);

        // Update size estimate and possibly spill.
        lock (_sizeLock)
        {
            // Very rough: assume each entry ≈ 64 bytes + size of key.
            _approxSizeBytes += 64;
            if (_approxSizeBytes > _cfg.MemoryBudgetBytes)
                _ = SpillLargestBucketAsync(); // fire‑and‑forget (back‑pressure via lock)
        }
    }

    private object? CreateKey(Row row)
    {
        // For demo we use an immutable array as a composite key.
